<?php
declare(strict_types=1);
require_once __DIR__.'/operators.php';require_once __DIR__.'/knowledge.php';
function support_brand_meta_valid(mixed $m): bool {return is_array($m)&&!array_diff(array_keys($m),['id','sha256','bytes','width','height'])&&preg_match('/^[a-f0-9]{32}$/D',$m['id']??'')&&preg_match('/^[a-f0-9]{64}$/D',$m['sha256']??'')&&is_int($m['bytes']??null)&&$m['bytes']>0&&$m['bytes']<=262144&&is_int($m['width']??null)&&$m['width']>0&&$m['width']<=512&&is_int($m['height']??null)&&$m['height']>0&&$m['height']<=512;}
function support_brand_profile_validate(array $a): void {
    if(isset($a['public_profile'])){$p=$a['public_profile'];if(!is_array($p)||array_diff(array_keys($p),['name','enabled','avatar'])||!is_string($p['name']??null)||strlen($p['name'])>120||!mb_check_encoding($p['name'],'UTF-8')||!is_bool($p['enabled']??null)||$p['enabled']&&trim($p['name'])===''||!array_key_exists('avatar',$p)||$p['avatar']!==null&&!support_brand_meta_valid($p['avatar']))support_failure(503,'operator_state_invalid');}
    if(isset($a['avatar_receipts'])){if(!is_array($a['avatar_receipts'])||count($a['avatar_receipts'])>8)support_failure(503,'operator_state_invalid');foreach($a['avatar_receipts']as $id=>$r)if(!support_valid_uuid($id)||!is_array($r)||!support_brand_meta_valid($r['asset']??null)||!is_int($r['expires']??null))support_failure(503,'operator_state_invalid');}
}
function support_public_agents(): array {
    if(!support_multi_operator())return [];
    try{return support_ops_store(function(array &$s){$agents=[];foreach($s['accounts']as $a){$p=$a['public_profile']??null;if(!$a['active']||!$p||!$p['enabled'])continue;$agents[]=['id'=>substr(hash_hmac('sha256','public-profile:'.$a['id'],support_security_key()),0,32),'name'=>$p['name'],'avatar'=>$p['avatar']?'support-avatar.php?id='.$p['avatar']['id']:null];}return $agents;});}catch(Throwable $e){return [];}
}
function support_public_sender_map(): array {
    if(!support_multi_operator())return [];
    try{return support_ops_store(function(array &$s){$map=[];foreach($s['accounts']as $a){$p=$a['public_profile']??null;if(!$a['active']||!$p||!$p['enabled'])continue;$principal='operator:'.hash('sha256',support_installation_id()."\0".$a['id']."\0".support_ops_version($a));$map[$principal]=['id'=>substr(hash_hmac('sha256','public-profile:'.$a['id'],support_security_key()),0,32),'name'=>$p['name'],'avatar'=>$p['avatar']?'support-avatar.php?id='.$p['avatar']['id']:null];}return $map;});}catch(Throwable $e){return [];}
}
function support_brand_select(array $receipts,?array $current,mixed $id): ?array {if(!is_string($id))support_failure(400,'invalid_brand_image');if($id==='')return null;support_content_id($id);if(($current['id']??null)===$id)return $current;foreach($receipts as $r)if($r['expires']>time()&&$r['asset']['id']===$id)return $r['asset'];support_failure(400,'invalid_brand_image');}
function support_brand_profile(array $context,array $input): array {
    support_ops_admin($context);$id=support_content_id($input['id']??null);$enabled=support_content_boolean($input['enabled']??null);$name=support_content_text($input['name']??'',120,!$enabled);
    return support_ops_store(function(array &$s)use($context,$id,$enabled,$name,$input){support_ops_recheck($s,$context);if(!isset($s['accounts'][$id]))support_failure(404,'operator_unavailable');$old=$s['accounts'][$id]['public_profile']??[];$avatar=array_key_exists('avatar_id',$input)?support_brand_select($s['accounts'][$id]['avatar_receipts']??[],$old['avatar']??null,$input['avatar_id']):($old['avatar']??null);$s['accounts'][$id]['public_profile']=['name'=>$name,'enabled'=>$enabled,'avatar'=>$avatar];support_ops_audit($s,$context['operator_id'],'public_profile_changed');return ['status'=>'success'];},true);
}
function support_brand_profiles(array $context): array {support_ops_admin($context);return support_ops_store(function(array &$s)use($context){support_ops_recheck($s,$context);return ['status'=>'success','profiles'=>array_values(array_map(fn($a)=>['id'=>$a['id'],'internal_name'=>$a['name'],'active'=>$a['active'],'profile'=>$a['public_profile']??['name'=>'','enabled'=>false,'avatar'=>null]],$s['accounts']))];});}
function support_brand_directory(): string {return support_private_dir(support_runtime_dir().'/brand-images');}
function support_brand_encode(array $file,bool $avatar): array {require_once __DIR__.'/profile-images.php';return support_profile_image_encode($file,$avatar);}
function support_brand_write(array $encoded): void {
    $dir=support_brand_directory();$files=glob($dir.'/*.webp');if($files===false||count($files)>=64)support_failure(429,'brand_image_capacity');$total=0;foreach($files as $f){if(is_link($f)||!is_file($f))support_failure(503,'brand_image_invalid');$total+=filesize($f);}if($total+strlen($encoded['binary'])>16777216)support_failure(429,'brand_image_capacity');$path=$dir.'/'.$encoded['meta']['id'].'.webp';if(file_exists($path)||is_link($path))support_failure(503,'brand_image_invalid');support_atomic_replace($path,$encoded['binary']);
}
function support_brand_upload(array $context,string $kind,string $target,string $operation,mixed $revision,array $file): array {
    support_ops_admin($context);if(!in_array($kind,['avatar','logo'],true)||!support_valid_uuid($operation))support_failure(400,'invalid_brand_image');if($kind==='avatar')support_content_id($target);$encoded=support_brand_encode($file,$kind==='avatar');
    return support_ops_store(function(array &$ops)use($context,$kind,$target,$operation,$revision,$encoded){support_ops_recheck($ops,$context);
        if($kind==='avatar'){if(!isset($ops['accounts'][$target]))support_failure(404,'operator_unavailable');$a=&$ops['accounts'][$target];$receipts=$a['avatar_receipts']??[];foreach($receipts as $id=>$r)if($r['expires']<=time())unset($receipts[$id]);if(isset($receipts[$operation])){if(!hash_equals($receipts[$operation]['asset']['sha256'],$encoded['meta']['sha256']))support_failure(409,'brand_upload_conflict');return ['status'=>'success','replayed'=>true,'asset'=>$receipts[$operation]['asset']];}if(count($receipts)>=8)support_failure(429,'brand_image_capacity');support_brand_write($encoded);$receipts[$operation]=['asset'=>$encoded['meta'],'expires'=>time()+86400];$a['avatar_receipts']=$receipts;support_ops_audit($ops,$context['operator_id'],'avatar_uploaded');return ['status'=>'success','replayed'=>false,'asset'=>$encoded['meta']];}
        return support_content_store(function(array &$s,bool &$changed)use($context,$operation,$revision,$encoded){foreach($s['uploads']as $id=>$r)if($r['expires']<=time())unset($s['uploads'][$id]);if(isset($s['uploads'][$operation])){if(!hash_equals($s['uploads'][$operation]['asset']['sha256'],$encoded['meta']['sha256']))support_failure(409,'brand_upload_conflict');return ['status'=>'success','replayed'=>true,'asset'=>$s['uploads'][$operation]['asset'],'revision'=>$s['revision']];}support_content_revision($s,$revision);if(count($s['uploads'])>=64)support_failure(429,'brand_image_capacity');support_brand_write($encoded);$s['uploads'][$operation]=['asset'=>$encoded['meta'],'expires'=>time()+86400];$changed=true;support_content_audit($s,$context,'logo_uploaded');return ['status'=>'success','replayed'=>false,'asset'=>$encoded['meta']];},true);
    },$kind==='avatar');
}
function support_brand_lookup(string $id,string $kind,bool $preview=false): ?array {
    if($kind==='logo')return support_content_store(function(array &$s,bool &$changed)use($id,$preview){$m=$s['settings']['logo'];if($m&&$m['id']===$id)return $m;if($preview)foreach($s['uploads']as $r)if($r['expires']>time()&&$r['asset']['id']===$id)return $r['asset'];return null;});
    return support_ops_store(function(array &$s)use($id,$preview){foreach($s['accounts']as $a){$p=$a['public_profile']??null;if($p&&$p['avatar']&&$p['avatar']['id']===$id&&($preview||$a['active']&&$p['enabled']))return $p['avatar'];if($preview)foreach($a['avatar_receipts']??[]as $r)if($r['expires']>time()&&$r['asset']['id']===$id)return $r['asset'];}return null;});
}
